args.sql:
SELECT artkey, readsec, wordlen, difflevel,
       (readsec * LOG(wordlen::numeric)) * CASE difflevel WHEN 'Basic' THEN 1.0 WHEN 'Intermediate' THEN 1.5 WHEN 'Advanced' THEN 2.0 ELSE 1.2 END AS ars_multiply
FROM articles WHERE artkey IN (1, 2, 3, 4, 5);

SELECT artkey, readsec, wordlen, difflevel,
       (readsec * (LN(wordlen::numeric) / LN(2))) / CASE difflevel WHEN 'Basic' THEN 1.0 WHEN 'Intermediate' THEN 1.5 WHEN 'Advanced' THEN 2.0 ELSE 1.2 END AS ars_log2
FROM articles WHERE artkey IN (1, 2, 3, 4, 5);
